package com.codepilot1c.core.tools.development;
import java.util.concurrent.CompletableFuture;
import com.google.gson.Gson;
import com.codepilot1c.core.tools.*;
import com.codepilot1c.core.tools.workspace.BackgroundJobRegistry;
import com.codepilot1c.core.edt.infobase.NativeInfobaseGateway;
@ToolMeta(name="edt_infobase_refresh",category="diagnostics",mutating=true,tags={"workspace","edt"})
public final class EdtInfobaseRefreshTool extends AbstractTool {
 public String getDescription(){return "Ask EDT to retrieve/compare actual bound-infobase changes and read native equality after workspace restart. Found conflicts are deferred, never applied. Optional compare_database exports stored main metadata and runs read-only Designer CompareCfg against DB configuration; returns owned report paths. Defaults never update configuration. Explicit update_incremental=true instead applies ALL current project changes by native incremental update (requires authorization to update that base), refuses pending FULL, and reports configuration_updated=true. Never starts Enterprise or silently falls back to FULL. Preserves binding/access; rejects a base owned by another project. Returns job_id; wait edt_operation_status. NOT_EQUAL remains a valid result, not automatic permission to update.";}
 public String getParameterSchema(){return "{\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"project\"],\"properties\":{\"project\":{\"type\":\"string\"},\"compare_database\":{\"type\":\"boolean\",\"default\":false},\"update_incremental\":{\"type\":\"boolean\",\"default\":false}}}";}
 protected CompletableFuture<ToolResult> doExecute(ToolParameters p){try{if(Boolean.TRUE.equals(p.getRaw().get("update_incremental"))&&Boolean.TRUE.equals(p.getRaw().get("compare_database")))throw new IllegalArgumentException("Choose update_incremental or compare_database, not both");String project=(String)p.getRaw().get("project");String id=BackgroundJobRegistry.getInstance().startJob("infobase-refresh",()->{var gateway=new NativeInfobaseGateway();var monitor=new org.eclipse.core.runtime.NullProgressMonitor();if(Boolean.TRUE.equals(p.getRaw().get("update_incremental")))return new Gson().toJson(gateway.updateIncremental(project,monitor));if(Boolean.TRUE.equals(p.getRaw().get("compare_database")))return new Gson().toJson(gateway.compareStoredConfigurations(project,gateway.stateRoot().resolve("compare-"+java.util.UUID.randomUUID()),monitor));return new Gson().toJson(gateway.refresh(project,monitor));});return CompletableFuture.completedFuture(ToolResult.success(new Gson().toJson(java.util.Map.of("job_id",id,"next_tool","edt_operation_status"))));}catch(Exception error){return CompletableFuture.completedFuture(ToolResult.failure(error.getMessage()));}}
}
